INSERT INTO posts (id, title, description, content, image, views, published_at) VALUES
    (
        1,
        'Введение в PHP 8.3',
        'Обзор возможностей PHP 8.3 для повседневной разработки.',
        '<p>PHP 8.3 — зрелая версия языка, в которой новые возможности появляются постепенно и почти не ломают существующий код. Для небольших проектов это хорошая новость: можно обновляться без масштабных переписываний и постепенно забирать только те улучшения, которые действительно нужны.</p><p>В этой статье соберём практический список возможностей PHP 8.3, которые пригодятся в повседневной работе: строгая типизация, readonly-классы, именованные аргументы и аккуратная работа с датами.</p><h2>Типы и readonly-классы</h2><p>Readonly-свойства появились раньше, но именно в связке с классами и конструктором они дают предсказуемые объекты-значения. Модель статьи, категории или пользователя удобно описывать как readonly-класс: после создания такой объект нельзя случайно изменить.</p><p>Отдельный выигрыш — явные типы параметров и возвращаемых значений. Когда сигнатура метода честно описывает вход и выход, контроллеры и репозитории становится проще читать, а ошибки ловятся раньше, чем попадут в шаблон.</p><h2>Даты без сюрпризов</h2><p>Для дат публикации лучше сразу выбрать DateTimeImmutable. Иммутабельные объекты не меняются при вызовах format, поэтому одну и ту же дату можно безопасно передавать между слоями приложения.</p><p>Форматирование оставляем представлению: в шаблоне выводим привычный формат, а в базе храним DATETIME в согласованной временной зоне. Это избавляет от расхождений между локальной машиной и сервером.</p><h2>Практический вывод</h2><p>Не нужно внедрять все новинки сразу. Достаточно выбрать несколько приёмов, которые уменьшают количество неявных преобразований и делают код понятнее. Для небольшого блога этого уже хватает.</p><p>Главный критерий — поддерживаемость. Если новая возможность упрощает чтение кода и снижает риск ошибок, она того стоит; если добавляет сложность без пользы, лучше отложить её до реальной задачи.</p>',
        '/assets/images/php-basics.svg',
        1240,
        '2026-10-30 09:00:00'
    ),
    (
        2,
        'PDO и подготовленные запросы',
        'Безопасная работа с MySQL через PDO и подготовленные выражения.',
        '<p>PDO даёт единый интерфейс для работы с базой данных и поддерживает подготовленные выражения. Это основной инструмент для безопасных запросов в небольших приложениях без ORM.</p><p>Подготовленные выражения отделяют структуру запроса от данных. База получает SQL и параметры по отдельности, поэтому значения не могут изменить логику запроса.</p><h2>Подключение и настройки</h2><p>При создании соединения важно включить режим исключений и отключить эмуляцию подготовленных выражений. Тогда ошибки не теряются, а запросы действительно выполняются на стороне MySQL.</p><p>Кодировку указываем в DSN, чтобы не зависеть от настроек сервера. Это особенно полезно, когда приложение запускается в контейнере и локально на разных машинах.</p><h2>Именованные параметры</h2><p>Именованные параметры читаются лучше знаков вопроса, особенно в запросах с несколькими условиями. Однако один и тот же именованный параметр нельзя использовать дважды без отдельной настройки, поэтому повторяющиеся значения лучше передавать через разные имена или позиционные параметры.</p><p>Числа и строки лучше приводить к ожидаемому типу до вызова метода. PDO умеет многое, но явное приведение делает намерения разработчика очевидными.</p><h2>Ошибки и транзакции</h2><p>Транзакции нужны там, где несколько изменений должны применяться вместе. Например, при связывании статьи с категориями: если вторая вставка не удалась, первая тоже должна быть отменена.</p><p>Не стоит заворачивать в транзакцию весь запрос целиком без необходимости. Чем короче транзакция, тем меньше блокировок и тем предсказуемее поведение под нагрузкой.</p><p>В результате получается простой набор правил: подготовленные выражения, явные типы, короткие транзакции и понятная обработка ошибок. Этого достаточно для большинства задач небольшого блога.</p>',
        '/assets/images/pdo.svg',
        980,
        '2026-10-31 10:30:00'
    ),
    (
        3,
        'Smarty: шаблоны без фреймворка',
        'Подключаем Smarty и строим шаблоны без фреймворка.',
        '<p>Smarty отделяет представление от логики приложения. Шаблоны наследуются, блоки переиспользуются, а контроллеры остаются компактными и не смешиваются с разметкой.</p><p>Для небольшого проекта этого достаточно: не нужен тяжёлый фреймворк, чтобы держать HTML в отдельных файлах и подключать общий каркас страницы.</p><h2>Наследование шаблонов</h2><p>Базовый layout описывает каркас страницы: шапку, основной блок и подвал. Дочерние шаблоны расширяют его и переопределяют только содержимое. Такой подход убирает копирование одинаковой разметки на каждой странице.</p><p>Все общие элементы — навигация, футер, карточки статей — удобно выносить в партиалы. Шаблон страницы тогда читается как список смысловых блоков, а не как длинный HTML-файл.</p><h2>Блоки и партиалы</h2><p>Партиал карточки статьи принимает объект поста и не знает, на какой странице он используется. Это позволяет применять один и тот же фрагмент на главной, в категории и в блоке похожих статей.</p><p>Если карточке нужен дополнительный параметр, его лучше передавать явно, а не полагаться на глобальные переменные. Явные зависимости проще отслеживать при изменении шаблонов.</p><h2>Безопасность вывода</h2><p>Пользовательские данные нужно экранировать при выводе. HTML-контент статьи — отдельный случай: он хранится как разметка и выводится без экранирования, но попадать в базу должен только из проверенного источника.</p><p>Такой подход даёт баланс: заголовки и описания защищены от нежелательной разметки, а тело статьи сохраняет форматирование.</p>',
        '/assets/images/smarty.svg',
        765,
        '2026-11-01 12:00:00'
    ),
    (
        4,
        'Индексы в MySQL',
        'Как индексы влияют на сортировку и выборку статей.',
        '<p>Индексы ускоряют выборку, но занимают место и замедляют запись. Важно понимать, какие запросы выполняются чаще всего и по каким полям действительно идёт поиск или сортировка.</p><p>Для блога типичны выборки последних статей, сортировка по просмотрам и фильтрация по категории. Под каждую из этих задач может понадобиться свой индекс.</p><h2>Как работает индекс</h2><p>Индекс — это дополнительная структура, которая позволяет базе быстрее находить нужные строки. Без индекса MySQL вынуждена просматривать таблицу целиком, и стоимость запроса растёт вместе с количеством записей.</p><p>При этом индекс полезен не всегда. Если запрос возвращает большую часть таблицы, полное сканирование может оказаться дешевле, чем чтение индекса и обращение к строкам.</p><h2>Какие индексы нужны блогу</h2><p>Индекс по дате публикации помогает строить ленты и списки статей. Индекс по количеству просмотров ускоряет популярные сортировки. Для связи статей и категорий обычно достаточно составного первичного ключа в промежуточной таблице.</p><p>Порядок полей в составном индексе имеет значение. Сначала идёт поле, по которому выполняется равенство, затем поле сортировки.</p><h2>Цена индексов</h2><p>Каждый индекс увеличивает размер базы и стоимость вставки или обновления. Поэтому не стоит индексировать всё подряд. Лучше измерить реальные запросы и добавлять индексы постепенно.</p><p>Периодически полезно смотреть план выполнения запроса. Он показывает, какие индексы используются, а где база всё ещё читает лишние строки.</p>',
        '/assets/images/mysql-indexes.svg',
        640,
        '2026-11-02 08:15:00'
    ),
    (
        5,
        'JOIN на практике',
        'Разбираем соединения таблиц на примере статей и категорий.',
        '<p>JOIN позволяет получить статьи вместе с категориями за один запрос. Главное — правильно выбрать тип соединения и не потерять записи, которые должны попасть в результат.</p><p>В схеме блога связь между статьями и категориями организована через промежуточную таблицу. Это классический вариант many-to-many, который встречается почти в каждом проекте.</p><h2>Связь many-to-many</h2><p>Промежуточная таблица хранит пары идентификаторов статьи и категории. Чтобы получить статьи с их категориями, нужно соединить три таблицы и сгруппировать результат.</p><p>Такой запрос удобно выполнять отдельно от основного списка, чтобы не размножать строки и не усложнять пагинацию.</p><h2>INNER JOIN и LEFT JOIN</h2><p>INNER JOIN возвращает только совпадающие строки. Если нужны все статьи, даже без категорий, потребуется LEFT JOIN. Выбор зависит от бизнес-правила: может ли статья существовать без категории.</p><p>Ошибка с типом соединения часто проявляется не сразу. Сначала всё работает на тестовых данных, а затем часть записей неожиданно исчезает из выдачи.</p><h2>Дубли и агрегаты</h2><p>Если у статьи несколько категорий, соединение вернёт несколько строк. Для списка статей это нежелательно, поэтому категории лучше загружать отдельным запросом и собирать в массив по идентификатору статьи.</p><p>Такой подход упрощает и подсчёт общего количества записей, и постраничный вывод. В результате запросы остаются предсказуемыми, а код — понятным.</p>',
        '/assets/images/sql-joins.svg',
        590,
        '2026-11-03 14:45:00'
    ),
    (
        6,
        'Docker для PHP-разработки',
        'Собираем воспроизводимое окружение для PHP-приложения.',
        '<p>Docker фиксирует версии PHP, MySQL и веб-сервера. Новый разработчик получает рабочее окружение одной командой и не тратит время на ручную настройку.</p><p>Для небольшого проекта достаточно двух сервисов: приложения и базы данных. Всё остальное можно добавлять по мере необходимости.</p><h2>Multi-stage сборка</h2><p>Зависимости через Composer удобно устанавливать в отдельном этапе. В итоговый образ попадает только готовый каталог vendor, без инструментов сборки и временных файлов.</p><p>Это уменьшает размер образа и снижает поверхность атаки. К тому же сборка становится быстрее за счёт кэширования слоёв.</p><h2>Тома для данных</h2><p>Данные MySQL должны жить вне контейнера, иначе они исчезнут при пересоздании. Именованный том решает эту задачу и сохраняет базу между запусками.</p><p>Каталоги с шаблонами компиляции тоже удобно выносить в том. Это особенно полезно при разработке: файлы не теряются при обновлении контейнера.</p><h2>Конфигурация через окружение</h2><p>Параметры подключения к базе лучше передавать через переменные окружения. Один и тот же образ тогда можно использовать в разных окружениях без пересборки.</p><p>Файл с секретами не должен попадать в репозиторий. В репозитории хранится только пример, а реальные значения остаются локально.</p><p>В итоге окружение становится воспроизводимым: команда поднимает проект, база заполняется начальными данными, а приложение сразу доступно по ожидаемому адресу.</p>',
        '/assets/images/docker-php.svg',
        510,
        '2026-11-04 09:40:00'
    ),
    (
        7,
        'Пагинация без фреймворка',
        'Постраничный вывод статей с сортировкой и ограничением выборки.',
        '<p>Пагинация нужна, когда список статей перестаёт помещаться на одну страницу. В запросе достаточно LIMIT и OFFSET, но важно правильно обработать граничные случаи.</p><p>Пользователь может вручную изменить номер страницы в адресе, поэтому контроллер не должен доверять этому значению.</p><h2>LIMIT и OFFSET</h2><p>LIMIT ограничивает количество строк в выборке, а OFFSET пропускает уже показанные. Для первой страницы смещение равно нулю, для второй — размеру страницы, и так далее.</p><p>Сортировка должна быть однозначной. Если сортировать только по дате, статьи с одинаковой датой могут менять порядок между запросами. Добавление идентификатора в сортировку устраняет неопределённость.</p><h2>Подсчёт страниц</h2><p>Общее количество записей считается отдельным запросом. Затем вычисляется число страниц и номер текущей страницы ограничивается допустимым диапазоном.</p><p>Если запрошена страница за пределами выборки, лучше показать последнюю, а не пустой экран. Это предсказуемое поведение, которое не ломает навигацию.</p><h2>Ссылки и состояние</h2><p>При переходе между страницами нужно сохранять выбранную сортировку. Иначе пользователь теряет контекст и каждый раз возвращается к сортировке по умолчанию.</p><p>Ссылки формируются с учётом текущих параметров. Это небольшое усложнение шаблона, но именно оно делает навигацию удобной.</p>',
        '/assets/images/pagination.svg',
        430,
        '2026-11-05 11:20:00'
    ),
    (
        8,
        'Валидация данных в контроллерах',
        'Проверяем параметры запроса до обращения к репозиторию.',
        '<p>Контроллер не должен доверять параметрам запроса. Номер страницы, режим сортировки и идентификатор статьи требуют проверки до обращения к базе данных.</p><p>Валидация в контроллере — это не только защита от ошибок, но и способ сделать поведение приложения предсказуемым.</p><h2>Идентификаторы</h2><p>Идентификатор статьи или категории должен быть положительным целым числом. Приводим значение к целому типу и отбрасываем недопустимые варианты.</p><p>После получения сущности из репозитория проверяем, что она существует. Если записи нет, выбрасываем исключение и показываем страницу 404.</p><h2>Сортировка и страницы</h2><p>Режим сортировки лучше сравнивать со списком допустимых значений, а не подставлять в SQL напрямую. Любое неизвестное значение сводим к значению по умолчанию.</p><p>Номер страницы приводим к положительному числу и ограничиваем сверху. Это защищает от отрицательных смещений и слишком больших запросов.</p><h2>Коды ответов</h2><p>Неверный параметр и отсутствующая сущность — разные ситуации. Для отсутствующей страницы уместен 404, для некорректного запроса можно вернуть 400.</p><p>Главное — не отдавать пользователю внутренние сообщения об ошибках. Подробности остаются в логах, а на экране появляется понятный текст.</p><p>Такая дисциплина делает контроллеры короткими и предсказуемыми, а поведение приложения — одинаковым при любых входных данных.</p>',
        '/assets/images/validation.svg',
        390,
        '2026-11-06 16:10:00'
    ),
    (
        9,
        'Чистые URL через mod_rewrite',
        'Настраиваем человекопонятные URL через mod_rewrite.',
        '<p>Чистые URL делают ссылки понятными, а маршрутизацию — предсказуемой. В Apache за это отвечает mod_rewrite, который перенаправляет запросы на единый входной файл.</p><p>В итоге посетитель видит адреса вида /post/1 и /category/2 вместо длинных параметров запроса.</p><h2>Правило в .htaccess</h2><p>Сначала проверяется, существует ли реальный файл или каталог. Если да, запрос обрабатывается как обычно. В противном случае он передаётся в index.php.</p><p>Такой порядок важен: статические файлы — стили, скрипты и изображения — должны отдаваться напрямую, без участия PHP.</p><h2>Разбор маршрута</h2><p>Входной файл получает путь из запроса и сопоставляет его с простыми шаблонами. Регулярные выражения подходят для числовых идентификаторов, а статические страницы можно сравнивать напрямую.</p><p>Порядок проверок имеет значение. Сначала обрабатываем более конкретные маршруты, затем общие, а в конце выбрасываем исключение для неизвестных адресов.</p><h2>Безопасность и предсказуемость</h2><p>Не стоит передавать в маршруты произвольные строки, которые затем попадают в SQL или файловую систему. Для сущностей лучше использовать числовые идентификаторы или заранее проверенные значения.</p><p>Единая точка входа упрощает обработку ошибок и логирование. Все запросы проходят через один сценарий, поэтому поведение приложения остаётся согласованным.</p>',
        '/assets/images/mod-rewrite.svg',
        320,
        '2026-11-07 13:05:00'
    ),
    (
        10,
        'Обработка ошибок и 404',
        'Обрабатываем отсутствующие страницы и отдаём корректный 404.',
        '<p>Ошибки бывают разными: отсутствующая страница, неверный параметр, проблема с базой данных. Важно не смешивать их в один сценарий и отдавать корректный код ответа.</p><p>Пользователь должен видеть понятное сообщение, а разработчик — подробности в журнале ошибок.</p><h2>Типы ошибок</h2><p>Ожидаемая ситуация — например, статья не найдена — не является сбоем приложения. Это нормальный результат запроса, который обрабатывается отдельным исключением.</p><p>Неожиданная ошибка — исключение базы данных или ошибка в коде — требует другого подхода. Её нужно залогировать и показать общую страницу 500.</p><h2>Исключения</h2><p>Для отсутствующих сущностей удобно завести отдельный класс исключения. Контроллер выбрасывает его, а входной файл перехватывает и выбирает нужный шаблон.</p><p>Такой подход отделяет бизнес-логику от формирования ответа и не засоряет контроллеры проверками кодов ответа.</p><h2>Коды и шаблоны</h2><p>Код ответа нужно выставлять до вывода страницы. Иначе браузер и поисковые системы получат неверную информацию о результате запроса.</p><p>Страницы ошибок лучше делать отдельными и минимальными. Они не должны зависеть от данных, которые могли стать причиной сбоя.</p><p>Отдельное логирование помогает поддерживать проект: видно, что именно произошло, без раскрытия внутренних деталей посетителю.</p>',
        '/assets/images/error-404.svg',
        280,
        '2026-11-08 10:00:00'
    ),
    (
        11,
        'CSS Grid для карточек статей',
        'Простая адаптивная сетка карточек без CSS-фреймворков.',
        '<p>Карточки статей удобно раскладывать через CSS Grid. Сетка адаптируется под ширину экрана без тяжёлых библиотек и лишних обёрток.</p><p>Главное — заранее определить минимальную ширину карточки и расстояние между элементами.</p><h2>auto-fill и minmax</h2><p>Комбинация auto-fill и minmax позволяет автоматически подбирать количество колонок. Пока карточки помещаются, они выстраиваются в ряд; когда места мало, сетка переносит их на новую строку.</p><p>minmax с конструкцией min(100%, 250px) защищает от переполнения на очень узких экранах.</p><h2>Структура карточки</h2><p>Внутри карточки достаточно нескольких блоков: обложка, заголовок, описание и метаданные. Карточка целиком является ссылкой, поэтому дополнительные вложенные ссылки не нужны.</p><p>Изображение занимает всю ширину и обрезается через object-fit. Это сохраняет единый ритм сетки независимо от исходных пропорций картинок.</p><h2>Hover и доступность</h2><p>При наведении карточка слегка приподнимается, а заголовок меняет цвет. Анимация должна быть короткой и ненавязчивой, чтобы не отвлекать от чтения.</p><p>Не стоит полагаться только на цвет. Состояние фокуса должно быть заметным, а вся карточка — доступной с клавиатуры как одна ссылка.</p>',
        '/assets/images/css-grid.svg',
        210,
        '2026-11-09 15:25:00'
    ),
    (
        12,
        'Итоги: структура небольшого проекта',
        'Структура небольшого блога и границы между слоями.',
        '<p>Небольшой проект проще поддерживать, когда код разделён на контроллеры, репозитории, модели и шаблоны. У каждого слоя есть понятная ответственность и минимум лишних связей.</p><p>При этом не стоит превращать блог в учебник по архитектуре. Достаточно нескольких ясных правил, которые помогают не запутаться при росте проекта.</p><h2>Слои и ответственность</h2><p>Контроллер принимает запрос, проверяет параметры и выбирает шаблон. Он не должен содержать SQL и не должен заниматься форматированием HTML.</p><p>Репозиторий отвечает за запросы к базе данных и преобразование строк в объекты. Шаблоны получают готовые данные и не знают, откуда они пришли.</p><h2>Что можно не делать</h2><p>Для блога не обязательны собственный контейнер зависимостей, сложная система событий или абстракция над каждой таблицей. Эти инструменты полезны, когда появляется реальная потребность, а не заранее.</p><p>Лучше держать код плоским и очевидным, пока проект небольшой. Рефакторинг проще выполнить, когда есть конкретные проблемы и понятные требования.</p><h2>Развитие проекта</h2><p>По мере роста появляются новые задачи: кеширование, поиск, админка, загрузка изображений. Каждую из них можно добавлять отдельным слоем, не переписывая всё приложение.</p><p>Главная ценность структуры — предсказуемость. Новый разработчик должен быстро понять, где искать логику запроса, где шаблон и где работа с базой данных.</p><p>Если это получается, значит архитектура выполняет свою задачу, независимо от количества файлов и модных терминов.</p>',
        '/assets/images/project-structure.svg',
        156,
        '2026-11-10 18:30:00'
    );

